import { themes, syncTheme, themeDialogHTML, setTheme } from './themes.js';
import { optionsFor, choiceKey, choicesHTML, galleryHTML } from './icon-options.js';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const statuses={testing:'◉ לבדיקה',ok:'✓ נבדק ותקין',fix:'! דורש תיקון',progress:'◷ בטיפול',idea:'✧ רעיון'};
const priorities={high:'גבוהה',normal:'רגילה',low:'נמוכה'};
let state,seed,db,view='designer',panel='panel-0',editing,undo=[],redo=[],history=[],saving=Promise.resolve(),drag,installEvent;
const id=()=>crypto.randomUUID(),copy=x=>structuredClone(x),children=p=>state.nodes.filter(n=>n.parent===p),find=i=>state.nodes.find(n=>n.id===i),safeIcon=s=>typeof s==='string'&&(/^(assets\/[A-Za-z0-9_.-]+\.(png|svg)|data:image\/(png|jpeg|webp|svg\+xml);base64,[A-Za-z0-9+/=]+)$/.test(s))?s:'app-icon.svg';
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),3500)}
function validate(s){if(!s||s.schema!==1||!Array.isArray(s.nodes)||s.nodes.length>3000)throw Error('מבנה הגיבוי אינו תקין');const ids=new Set;for(const n of s.nodes){if(typeof n.id!=='string'||ids.has(n.id)||['ribbon','backlog'].includes(n.id)||!['button','panel','stack','dropdown','separator'].includes(n.type)||typeof n.label!=='string'||typeof n.parent!=='string')throw Error('פריט לא תקין בגיבוי');ids.add(n.id);if(n.type==='button'&&(!statuses[n.status]||!priorities[n.priority]))throw Error('סטטוס או עדיפות לא תקינים');if(n.icon&&safeIcon(n.icon)!==n.icon)throw Error('אייקון לא נתמך');for(const k of ['notes','fix','fixedVersion','tooltip'])if(n[k]!=null&&typeof n[k]!=='string')throw Error('שדה טקסט לא תקין');}for(const n of s.nodes){const p=s.nodes.find(x=>x.id===n.parent);if(n.type==='panel'&&n.parent!=='ribbon')throw Error('קבוצה חייבת להיות בסרגל');if(n.type!=='panel'&&!p&&n.parent!=='backlog')throw Error('מיקום חסר');if(p&&(!['panel','stack','dropdown'].includes(p.type)||(['stack','dropdown'].includes(n.type)&&p.type!=='panel')||(n.type==='separator'&&p.type!=='dropdown')))throw Error('קינון לא נתמך');if(n.parent==='backlog'&&n.type!=='button')throw Error('רק כלים נשמרים ברעיונות');}return s;}
async function openDB(){return new Promise((resolve,reject)=>{const r=indexedDB.open('hoek-ribbon-studio',1);r.onupgradeneeded=()=>r.result.createObjectStore('workspace');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}
async function readDB(){return new Promise((resolve,reject)=>{const r=db.transaction('workspace').objectStore('workspace').get('current');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}
function persist(){const payload=copy({state,undo,redo,history});$('#save-state').textContent='שומר…';saving=saving.catch(()=>{}).then(()=>new Promise((resolve,reject)=>{if(!db){try{localStorage.setItem('hoek-workspace',JSON.stringify(payload));resolve()}catch(e){reject(e)}return}const tx=db.transaction('workspace','readwrite');tx.objectStore('workspace').put(payload,'current');tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error)})).then(()=>{$('#save-state').textContent='✓ נשמר במכשיר'}).catch(()=>{$('#save-state').textContent='השמירה נכשלה — יש לייצא גיבוי';toast('אין מספיק מקום לשמירה. ייצאו גיבוי כעת.');});}
function change(label,fn){const before=copy(state);fn();try{validate(state)}catch(e){state=before;toast(e.message);return}undo.push({label,state:before});undo=undo.slice(-40);redo=[];history.unshift({label,time:new Date().toISOString()});history=history.slice(0,120);persist();render()}
function travel(from,to,prefix){if(!from.length)return;const entry=from.pop();to.push({label:entry.label,state:copy(state)});state=entry.state;history.unshift({label:prefix+entry.label,time:new Date().toISOString()});persist();render()}
function matches(n){const q=$('#search').value.toLowerCase();return(!q||[n.label,n.notes,n.fix,n.tooltip,n.source?.command].join(' ').toLowerCase().includes(q))&&(!$('#status-filter').value||n.status===$('#status-filter').value)&&(!$('#priority-filter').value||n.priority===$('#priority-filter').value)}
function visible(n){return n.type==='button'?matches(n):n.type==='separator'?false:children(n.id).some(visible)||!children(n.id).length}
function badge(n){return `<span class="badge ${esc(n.status)}">${statuses[n.status]||''}</span>`}
function card(n,list=false){return `<div class="node" data-node="${esc(n.id)}">${!list?`<button class="handle" data-drag="${esc(n.id)}" aria-label="גרירת ${esc(n.label)}">⠿</button>`:''}<button class="card" data-edit="${esc(n.id)}" title="${esc(n.tooltip||n.label)}"><img src="${esc(safeIcon(n.icon))}" alt=""><span class="name">${esc(n.label)}</span>${list&&n.fix?`<small>${esc(n.fix)}</small>`:''}${badge(n)}${n.priority==='high'?'<span class="badge fix">עדיפות גבוהה</span>':''}</button></div>`}
function nodeHTML(n){if(n.type!=='separator'&&!visible(n))return '';if(n.type==='button')return card(n);if(n.type==='separator')return `<div class="node separator" data-node="${esc(n.id)}"><button class="handle" data-edit="${esc(n.id)}" aria-label="עריכת מפריד">⋯</button></div>`;return `<div class="node group" data-node="${esc(n.id)}"><button class="handle" data-drag="${esc(n.id)}" aria-label="גרירת קבוצה">⠿</button><div class="group-head"><button data-toggle="${esc(n.id)}">${n.type==='dropdown'?'▾':'☰'} ${esc(n.label)} <small>(${children(n.id).filter(x=>x.type==='button').length})</small></button><button data-edit="${esc(n.id)}" aria-label="עריכת קבוצה">•••</button></div><div class="group-items" data-container="${esc(n.id)}">${children(n.id).map(nodeHTML).join('')}</div></div>`}
function render(){document.body.dataset.theme=state.theme||'original';if(panel!=='all'&&!find(panel))panel='all';const buttons=state.nodes.filter(n=>n.type==='button');$('#metrics').innerHTML=[['כלים בסביבה',buttons.length],['נבדקו ותקינים',buttons.filter(n=>n.status==='ok').length],['צריכים תשומת לב',buttons.filter(n=>['fix','progress'].includes(n.status)).length],['רעיונות להמשך',children('backlog').length]].map(([t,v])=>`<div class="metric"><span>${t}</span><b>${v.toString().padStart(2,'0')}</b></div>`).join('');$('#metrics').hidden=view==='icons';const titles={icons:['בוחרים את האייקון.','חלופות לכל כלי, בלי לשנות את הפעולה שלו.','חלופות אייקונים'],designer:['מעצבים את הסרגל.','כל הכלים שלך. מקום לרעיונות הבאים.','מבנה הסרגל'],backlog:['המקום לרעיון הבא.','מחשבה קטנה היום. כלי שימושי מחר.','רעיונות להמשך'],testing:['בודקים. משפרים.','כל מה שצריך תשומת לב, במקום אחד.','בדיקות ותיקונים'],history:['חופש לשנות כיוון.','השינויים האחרונים בסביבת העבודה שלך.','היסטוריית שינויים']};$('#heading').textContent=titles[view][0];$('#subtitle').textContent=titles[view][1];$('#view-label').innerHTML=titles[view][2]+' <span>LIVE DRAFT</span>';$$('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('#undo').disabled=!undo.length;$('#redo').disabled=!redo.length;$('#add').hidden=['history','icons'].includes(view);$('#add').textContent=view==='backlog'?'＋ רעיון חדש':'＋ כפתור חדש';$('#add-panel').hidden=view!=='designer';$('#filters').hidden=view==='history';$('#hint').hidden=view!=='designer';$('#panel-tabs').hidden=!['designer','icons'].includes(view);$('#panel-tabs').innerHTML=`<button data-panel="all" class="${panel==='all'?'active':''}">All panels</button>`+children('ribbon').map(n=>`<button data-panel="${esc(n.id)}" class="${panel===n.id?'active':''}">${esc(n.label)}</button>`).join('');
if(view==='designer'){$('#content').innerHTML=children('ribbon').filter(n=>panel==='all'||n.id===panel).filter(visible).map(n=>`<section class="panel" data-node="${esc(n.id)}"><div class="panel-head"><span class="panel-title">${esc(n.label)} <small>${state.nodes.filter(x=>x.type==='button'&&(x.parent===n.id||find(x.parent)?.parent===n.id)).length} tools</small></span><div><button data-new-group="${esc(n.id)}">＋ תפריט</button> <button data-edit="${esc(n.id)}" aria-label="עריכת ${esc(n.label)}">•••</button></div></div><div class="panel-items" data-container="${esc(n.id)}">${children(n.id).map(nodeHTML).join('')||'<span class="empty">אפשר לגרור לכאן כלי</span>'}</div></section>`).join('')||'<div class="empty"><b>אין כלים בתצוגה הזו</b>אפשר לשנות את הסינון או להוסיף קבוצה.</div>'}
else if(view==='icons')$('#content').innerHTML=galleryHTML(state.nodes.filter(n=>['button','dropdown'].includes(n.type)).filter(n=>(panel==='all'||n.parent===panel||find(n.parent)?.parent===panel)&&matches(n)),state.nodes);
else if(view==='history')$('#content').innerHTML=history.map(h=>`<div class="history-row"><span>${esc(h.label)}</span><time>${new Date(h.time).toLocaleString('he-IL')}</time></div>`).join('')||'<div class="empty"><b>דף חדש.</b>השינויים שלך יופיעו כאן.</div>';
else{let items=buttons.filter(n=>view==='backlog'?n.parent==='backlog':['testing','fix','progress'].includes(n.status)).filter(matches);if(view==='testing')items.sort((a,b)=>(a.priority==='high'?-1:0)-(b.priority==='high'?-1:0));$('#content').innerHTML=`<div class="list">${items.map(n=>card(n,true)).join('')}</div>`+(items.length?'':`<div class="empty"><b>${view==='backlog'?'מה חסר בסרגל שלך?':'אין כלים שממתינים כאן.'}</b>${view==='backlog'?'הוסיפו רעיון ושמרו אותו להמשך.':'שנו את הסינון או חזרו לעיצוב הסרגל.'}</div>`)}
syncTheme(state);
}
const opts=(map,value)=>Object.entries(map).map(([k,v])=>`<option value="${esc(k)}" ${k===value?'selected':''}>${esc(v)}</option>`).join('');
function destinations(n){return [{id:'backlog',label:'רעיונות / Backlog'},...state.nodes.filter(x=>['panel','stack','dropdown'].includes(x.type)&&x.id!==n.id&&x.parent!==n.id)].filter(x=>n.type==='button'?true:n.type==='panel'?false:n.type==='separator'?find(x.id)?.type==='dropdown':find(x.id)?.type==='panel')}
function edit(n){editing=copy(n);const isButton=n.type==='button',isPanel=n.type==='panel';$('#editor-body').innerHTML=`<div class="edit-icon"><img id="icon-preview" src="${esc(safeIcon(n.icon))}" alt=""><div><b>${esc(n.label||'כלי חדש')}</b><small>${n.source?'מתוך חבילת 3.9.3':'פריט תכנון חדש'}</small></div></div>${optionsFor(n).length?`<section class="editor-icon-picker"><h3>בחירת אייקון</h3><p>הבחירה תוחל בלחיצה על שמירת שינויים.</p>${choicesHTML(n,true)}</section>`:''}<div class="fields"><label class="full">שם<textarea name="label" required maxlength="140" rows="2" dir="auto">${esc(n.label)}</textarea></label>${isButton?`<label>סטטוס<select name="status">${opts(statuses,n.status)}</select></label><label>עדיפות<select name="priority">${opts(priorities,n.priority)}</select></label>`:''}${!isPanel?`<label class="full">מיקום<select name="parent">${destinations(n).map(x=>`<option value="${esc(x.id)}" ${n.parent===x.id?'selected':''}>${esc(x.label)}${find(x.id)?.type==='panel'?'':' · '+esc(find(find(x.id)?.parent)?.label||'')}</option>`).join('')}</select></label>`:''}<label>מיקום בסדר<input name="order" type="number" min="1" max="3001" value="${Math.max(1,children(n.parent).findIndex(x=>x.id===n.id)+1)}"></label>${['stack','dropdown'].includes(n.type)?`<label>סוג קבוצה<select name="type"><option value="dropdown" ${n.type==='dropdown'?'selected':''}>תפריט נפתח</option><option value="stack" ${n.type==='stack'?'selected':''}>ערימה (2–3 כלים ב-Revit)</option></select></label>`:''}${n.type!=='separator'&&n.type!=='panel'?`<label class="full">תיאור / Tooltip<textarea name="tooltip" dir="auto">${esc(n.tooltip)}</textarea></label><label class="full">החלפת אייקון (PNG / JPG / WebP)<input id="icon-file" type="file" accept="image/png,image/jpeg,image/webp"></label>`:''}${isButton?`<label class="full">הערות ורעיונות<textarea name="notes" dir="auto" placeholder="מה כדאי לשפר?">${esc(n.notes)}</textarea></label><label class="full">מה דורש תיקון / מה לבדוק<textarea name="fix" dir="auto">${esc(n.fix)}</textarea></label><label class="full">גרסה שבה תוקן<input name="fixedVersion" value="${esc(n.fixedVersion)}" placeholder="למשל 3.9.4"></label>`:''}</div>${n.source?`<details><summary>מידע מקורי מהחבילה</summary><pre>${esc(JSON.stringify(n.source,null,2))}</pre></details>`:''}`;$('#delete').hidden=!find(n.id);$('#editor').showModal();}
function create(type,parent){edit({id:id(),type,parent,label:'',icon:'',status:type==='button'?'idea':undefined,priority:'normal',notes:'',fix:'',tooltip:'',fixedVersion:''})}
function reorder(n,parent,position){const index=state.nodes.findIndex(x=>x.id===n.id);if(index>=0)state.nodes.splice(index,1);n.parent=parent;const siblings=children(parent);const target=siblings[Math.max(0,position)];if(target)state.nodes.splice(state.nodes.indexOf(target),0,n);else{const last=siblings.at(-1);state.nodes.splice(last?state.nodes.indexOf(last)+1:state.nodes.length,0,n)}}
$('#edit-form').onsubmit=e=>{e.preventDefault();const data=new FormData(e.target);const n=copy(editing);for(const key of ['label','status','priority','tooltip','notes','fix','fixedVersion','type'])if(data.has(key))n[key]=String(data.get(key)).trim();if(!n.label)return;const parent=data.get('parent')||n.parent;if(n.type==='stack'&&children(n.id).some(x=>x.type==='separator')){toast('יש להסיר מפרידים לפני שינוי לערימה');return}change('עריכה: '+n.label,()=>reorder(n,parent,Number(data.get('order'))-1));$('#editor').close();};
$('#editor-body').onchange=async e=>{if(e.target.id!=='icon-file')return;const f=e.target.files[0];if(!f)return;if(f.size>2*1024*1024||!['image/png','image/jpeg','image/webp'].includes(f.type)){toast('בחרו תמונה עד 2MB');return}const reader=new FileReader;reader.onload=()=>{editing.icon=reader.result;delete editing.iconChoice;$('#icon-preview').src=reader.result;const picker=$('.editor-icon-picker .icon-choices');if(picker)picker.outerHTML=choicesHTML(editing,true)};reader.readAsDataURL(f)};
$('#delete').onclick=()=>{if(!confirm('למחוק את הפריט? כלים מתוך קבוצה שנמחקה יעברו לרעיונות.'))return;change('מחיקה: '+editing.label,()=>{const remove=new Set([editing.id]);let again=true;while(again){again=false;for(const n of state.nodes)if(remove.has(n.parent)&&!remove.has(n.id)){remove.add(n.id);again=true}}state.nodes=state.nodes.filter(n=>{if(!remove.has(n.id))return true;if(n.id!==editing.id&&n.type==='button'){n.parent='backlog';return true}return false})});$('#editor').close()};
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-close'))b.closest('dialog').close();if(b.dataset.view){view=b.dataset.view;render()}if(b.dataset.panel){panel=b.dataset.panel;render()}if(b.dataset.edit)edit(find(b.dataset.edit));if(b.dataset.newGroup)create('dropdown',b.dataset.newGroup);if(b.dataset.toggle){const c=b.closest('.group').querySelector('.group-items');c.hidden=!c.hidden;b.setAttribute('aria-expanded',String(!c.hidden));}});
$('#add').onclick=()=>create('button',view==='backlog'?'backlog':panel!=='all'?panel:children('ribbon')[0]?.id||'backlog');$('#add-panel').onclick=()=>create('panel','ribbon');$('#undo').onclick=()=>travel(undo,redo,'ביטול: ');$('#redo').onclick=()=>travel(redo,undo,'שחזור: ');for(const x of ['search','status-filter','priority-filter'])$('#'+x).addEventListener('input',render);
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'&&!e.target.closest('input,textarea,select,dialog')){e.preventDefault();e.shiftKey?travel(redo,undo,'שחזור: '):travel(undo,redo,'ביטול: ')}});
document.addEventListener('click',e=>{const b=e.target.closest('[data-icon-key]');if(!b)return;const staged=b.hasAttribute('data-stage-icon');const n=staged?editing:find(b.dataset.iconNode);if(!n)return;const option=optionsFor(n).find(o=>o.key===b.dataset.iconKey);if(!option)return;if(staged){editing.icon=option.src;editing.iconChoice=option.key;$('#icon-preview').src=option.src;b.closest('.icon-choices').outerHTML=choicesHTML(editing,true);}else if(choiceKey(n)!==option.key){change('בחירת אייקון: '+n.label+' · '+option.title,()=>{n.icon=option.src;n.iconChoice=option.key;});toast('האייקון נבחר ונשמר');}});
$('#settings').onclick=()=>$('#menu').showModal();
function download(name,data){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
async function embedIcons(s){for(const n of s.nodes){if(n.icon?.startsWith('assets/')){const r=await fetch(n.icon);if(!r.ok)throw Error('אייקון חסר בגיבוי');const blob=new Blob([await r.arrayBuffer()],{type:n.icon.endsWith('.svg')?'image/svg+xml':'image/png'});n.icon=await new Promise((res,rej)=>{const reader=new FileReader;reader.onload=()=>res(reader.result);reader.onerror=rej;reader.readAsDataURL(blob)})}}return s}
$('#backup').onclick=async()=>{try{await saving;const data=await embedIcons(copy(state));download('hoek-backup-'+new Date().toISOString().slice(0,10)+'.json',{format:'hoek-backup',version:1,state:data,history,exportedAt:new Date().toISOString()});toast('קובץ הגיבוי מוכן')}catch(e){toast(e.message)}};
$('#import').onclick=()=>{$('#menu').close();$('#import-file').click()};$('#import-file').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>30*1024*1024)throw Error('קובץ גדול מדי (עד 30MB)');const data=JSON.parse(await f.text());if(data.format!=='hoek-backup'||data.version!==1)throw Error('זה אינו גיבוי של Hoek Studio');validate(data.state);if(!confirm('להחליף את התכנון הנוכחי בגיבוי? ניתן לבטל את הייבוא.'))return;change('ייבוא גיבוי',()=>{state=data.state;history=Array.isArray(data.history)?data.history.filter(h=>h&&typeof h.label==='string'&&typeof h.time==='string').slice(0,119):[]});toast('הגיבוי נטען בהצלחה')}catch(e){toast(e.message)}finally{e.target.value=''}};
$('#spec').onclick=()=>{download('hoek-planning-spec.json',{purpose:'Planning specification; review before implementing in Revit',state,exportedAt:new Date().toISOString()});$('#menu').close();toast('מפרט התכנון יוצא')};
$('#help').onclick=()=>{alert('פתחו את האפליקציה פעם אחת עם אינטרנט והמתינו להודעת ״מוכנה לאופליין״.\n\nב-iPhone: Safari ← שיתוף ← הוסף למסך הבית.\nב-Android: Chrome ← תפריט ← התקנת אפליקציה.\n\nלשימוש בטלפון נדרשת כתובת HTTPS. בשרת המקומי אפשר לבדוק אופליין דרך localhost במחשב.\n\nהנתונים נשמרים במכשיר ובדפדפן הזה בלבד. גיבוי מעביר אותם למכשיר אחר.');};
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installEvent=e;$('#install').hidden=false});$('#install').onclick=async()=>{if(installEvent){await installEvent.prompt();installEvent=null;$('#install').hidden=true}};
function canMove(n,p){const dest=find(p);if(n.type==='button')return p==='backlog'||['panel','dropdown','stack'].includes(dest?.type);if(['stack','dropdown'].includes(n.type))return dest?.type==='panel';return false}
document.addEventListener('pointerdown',e=>{const h=e.target.closest('[data-drag]');if(!h||e.button!==0)return;e.preventDefault();const n=find(h.dataset.drag);drag={id:n.id,x:e.clientX,y:e.clientY,pointer:e.pointerId,active:false};h.setPointerCapture(e.pointerId)});
document.addEventListener('pointermove',e=>{if(!drag||e.pointerId!==drag.pointer)return;if(!drag.active&&Math.hypot(e.clientX-drag.x,e.clientY-drag.y)<7)return;if(!drag.active){drag.active=true;drag.ghost=document.createElement('div');drag.ghost.className='drag-label';drag.ghost.textContent=find(drag.id).label;document.body.append(drag.ghost);document.querySelector(`[data-node="${CSS.escape(drag.id)}"]`)?.classList.add('dragging')}drag.ghost.style.left=e.clientX+14+'px';drag.ghost.style.top=e.clientY+10+'px';$$('.drop-target').forEach(x=>x.classList.remove('drop-target'));const hit=document.elementFromPoint(e.clientX,e.clientY);const container=hit?.closest('[data-container]');const n=find(drag.id);drag.target=null;if(container&&canMove(n,container.dataset.container)&&container.dataset.container!==n.id){const item=hit.closest('[data-node]');const target=item&&item.dataset.node!==n.id&&find(item.dataset.node)?.parent===container.dataset.container?item:null;drag.target={parent:container.dataset.container,before:target?.dataset.node};(target||container).classList.add('drop-target')}if(e.clientY>innerHeight-90)window.scrollBy(0,10);else if(e.clientY<120)window.scrollBy(0,-10)});
function finishDrag(cancel=false){if(!drag)return;const d=drag;drag=null;d.ghost?.remove();$$('.drop-target,.dragging').forEach(x=>x.classList.remove('drop-target','dragging'));if(d.active&&d.target&&!cancel){const n=find(d.id),siblings=children(d.target.parent).filter(x=>x.id!==n.id);const pos=d.target.before?siblings.findIndex(x=>x.id===d.target.before):siblings.length;change('העברה: '+n.label,()=>reorder(n,d.target.parent,pos));toast('המיקום עודכן')}}document.addEventListener('pointerup',()=>finishDrag());document.addEventListener('pointercancel',()=>finishDrag(true));
async function boot(){try{seed=await(await fetch('seed.json')).json();try{db=await openDB()}catch{}let saved;try{saved=db?await readDB():JSON.parse(localStorage.getItem('hoek-workspace'))}catch{}state=validate(saved?.state||copy(seed));undo=(saved?.undo||[]).filter(x=>{try{validate(x.state);return true}catch{return false}});redo=saved?.redo||[];history=saved?.history||[];render();$('#save-state').textContent='✓ נשמר במכשיר';if(navigator.storage?.persist)navigator.storage.persist().catch(()=>{});if('serviceWorker'in navigator){try{await navigator.serviceWorker.register('sw.js');await navigator.serviceWorker.ready;$('#offline-state').textContent='✓ מוכנה לאופליין'}catch{$('#offline-state').textContent='אופליין דורש HTTPS או localhost'}}else $('#offline-state').textContent='הדפדפן אינו תומך באופליין';}catch(e){$('#content').innerHTML='<div class="empty"><b>לא ניתן לטעון את סביבת העבודה.</b>יש לפתוח דרך השרת המקומי או כתובת האתר.</div>';$('#save-state').textContent=e.message;}}
function openThemes(){document.querySelector('#theme-grid').innerHTML=themeDialogHTML(state,seed);document.querySelector('#themes-dialog').showModal();}
document.querySelector('#open-themes').onclick=()=>{document.querySelector('#menu').close();openThemes();};
document.querySelector('#themes-dialog').addEventListener('close',()=>{if(!state.themeIntroSeen){state.themeIntroSeen=true;persist();}});
document.querySelector('#theme-grid').onclick=e=>{const b=e.target.closest('[data-choose-theme]');if(!b)return;const theme=themes.find(t=>t.id===b.dataset.chooseTheme);change('ערכת עיצוב: '+theme.name,()=>setTheme(state,theme.id));document.querySelector('#themes-dialog').close();toast('הערכה הוחלה. אפשר להמשיך לערוך כל כלי.');};
boot().then(()=>{if(state&&!state.themeIntroSeen)openThemes();});
